11:   HomeIcon,
12:   StatementIcon,
13:   TransactionIcon,
14:   LogoutIcon,
15:   ArrowLeftIcon,
16: } from "./components/Icons";
17: import { ROUTES, MESSAGES, STORAGE_KEYS } from "./constants";
18: import { clearLocalStorage, getLocalStorageItem } from "./utils/windowUtils";
19: import "./styles/tokens.css";
20: import styles from "./NavigationDrawer.module.css";
21: 
22: const NAV_ITEMS = [
23:   {
24:     path: ROUTES.ROOT,
25:     route: ROUTES.DASHBOARD,
26:     icon: <HomeIcon />,
27:     label: "Inicio",
28:   },
29:   {
30:     path: ROUTES.STATEMENT,
31:     route: ROUTES.STATEMENT,
32:     icon: <StatementIcon />,
33:     label: "Extrato",
34:   },
35:   {
36:     path: ROUTES.TRANSACTIONS,
37:     route: ROUTES.TRANSACTIONS,
38:     icon: <TransactionIcon />,
39:     label: "Transação",
40:   },
41: ] as const;
42: 
43: export default function Root() {
44:   const { isMobile, isSidebarOpen, closeSidebar } = useMobile();
45:   const currentPath = useCurrentPath();
46:   const {
47:     accounts,
48:     selectedAccountId,
49:     loading,
50:     error,
51:     retryLoadAccounts,
52:   } = useAccounts();
53: 
54:   const handleNavigate = useCallback(
55:     (url: string) => {
56:       if (isMobile) {
57:         closeSidebar();
58:       }
59:       navigateToUrl(url);
60:     },
61:     [isMobile, closeSidebar]
62:   );
63: 
64:   useEffect(() => {
65:     const handleRouteChange = () => {
66:       if (isMobile && isSidebarOpen) {
67:         closeSidebar();
68:       }
69:     };
70: 
71:     window.addEventListener("single-spa:routing-event", handleRouteChange);
72:     window.addEventListener("popstate", handleRouteChange);
73: 
74:     return () => {
75:       window.removeEventListener("single-spa:routing-event", handleRouteChange);
76:       window.removeEventListener("popstate", handleRouteChange);
77:     };
78:   }, [isMobile, isSidebarOpen, closeSidebar]);
79: 
80:   const isActive = (path: string) => {
81:     if (path === ROUTES.ROOT) {
82:       return currentPath === ROUTES.ROOT || currentPath === ROUTES.DASHBOARD;
83:     }
84:     return currentPath === path || currentPath.startsWith(path + "/");
85:   };
86: 
87:   const handleLogout = useCallback(() => {
88:     clearLocalStorage();
89:     navigateToUrl(ROUTES.AUTH);
90:   }, []);
91: 
92:   if (loading) {
93:     return (
94:       <aside
95:         className={`${styles.sidebar} ${
96:           isMobile && isSidebarOpen ? styles.open : ""
97:         }`}
98:       >
99:         <div className={styles.sidebarContent}>
100:           <Loading text={MESSAGES.LOADING} size="small" />
101:         </div>
102:       </aside>
103:     );
104:   }
105: 
106:   const showError = error && accounts.length === 0;
107:   const userName = getLocalStorageItem(STORAGE_KEYS.USER_NAME) || "";
108: 
109:   return (
110:     <aside
111:       className={`${styles.sidebar} ${
112:         isMobile && isSidebarOpen ? styles.open : ""
113:       }`}
114:     >
115:       <div className={styles.sidebarContent}>
116:         <div className={styles.header}>
117:           {isMobile && (
118:             <button
119:               className={styles.closeButton}
120:               onClick={closeSidebar}
121:               aria-label="Fechar menu"
122:             >
123:               <ArrowLeftIcon />
124:             </button>
125:           )}
126:           {userName && selectedAccountId ? (
127:             <UserProfile
128:               userName={userName}
129:               accountNumber={selectedAccountId}
130:               agency="0001"
131:             />
132:           ) : (
133:             <Text
134:               variant="subtitle"
135:               weight="bold"
136:               className={styles.greeting}
137:             >
138:               {MESSAGES.WELCOME} {userName}
139:             </Text>
140:           )}
141:         </div>
142: 
143:         {showError && (
144:           <ErrorMessage message={error} onRetry={retryLoadAccounts} />
145:         )}
146: 
147:         {!showError && accounts.length === 0 && !loading && (
148:           <div className={styles.emptyState}>
149:             <Text variant="small" color="gray600">
150:               {MESSAGES.NO_ACCOUNTS}
151:             </Text>
152:           </div>
153:         )}
154: 
155:         <nav className={styles.navLinks} aria-label="Navegação principal">
156:           {NAV_ITEMS.map((item) => (
157:             <NavLink
158:               key={item.path}
159:               icon={item.icon}
160:               label={item.label}
161:               isActive={isActive(item.path)}
162:               onClick={() => handleNavigate(item.route)}
163:             />
164:           ))}
165:         </nav>
166: 
167:         <button
168:           className={`${styles.navLink} ${styles.logoutButton}`}
169:           onClick={handleLogout}
170:           aria-label="Sair da aplicação"
171:         >
172:           <div className={styles.navLinkContent}>
173:             <LogoutIcon aria-hidden="true" />
174:             <Text variant="body" weight="regular">
175:               Sair
176:             </Text>
177:           </div>
178:         </button>
179:       </div>
180:     </aside>
181:   );
182: }

