1: import { getApiBaseUrl } from "@/config/api.config";
2: import {
3:   getLocalStorageItem,
4:   removeLocalStorageItem,
5:   isWindowAvailable,
6: } from "./windowUtils";
7: import { STORAGE_KEYS, ROUTES } from "@/constants";
8: 
9: function getAuthToken(): string | null {
10:   return getLocalStorageItem(STORAGE_KEYS.TOKEN);
11: }
12: 
13: export async function fetchApi(
14:   url: string,
15:   options: RequestInit = {}
16: ): Promise<Response> {
17:   const token = getAuthToken();
18:   const headers: HeadersInit = {
19:     "Content-Type": "application/json",
20:     ...options.headers,
21:   };
22: 
23:   if (token) {
24:     headers["Authorization"] = `Bearer ${token}`;
25:   }
26: 
27:   const API_BASE_URL = getApiBaseUrl();
28: 
29:   try {
30:     const response = await fetch(`${API_BASE_URL}${url}`, {
31:       ...options,
32:       headers,
33:     });
34: 
35:     if (!response.ok) {
36:       if (response.status === 401) {
37:         removeLocalStorageItem(STORAGE_KEYS.TOKEN);
38:         if (isWindowAvailable()) {
39:           window.location.href = ROUTES.AUTH;
40:         }
41:         const errorText = await response
42:           .text()
43:           .catch(() => response.statusText);
44:         throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
45:       }
46:       const errorText = await response.text().catch(() => response.statusText);
47:       throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
48:     }
49: 
50:     return response;
51:   } catch (error) {
52:     if (error instanceof TypeError && error.message.includes("fetch")) {
53:       throw new Error(
54:         "Erro de conexão: Não foi possível conectar ao servidor. Verifique se o backend está rodando."
55:       );
56:     }
57:     if (error instanceof Error && error.message.includes("CORS")) {
58:       throw new Error(
59:         "Erro de CORS: O servidor não permite requisições desta origem."
60:       );
61:     }
62:     throw error;
63:   }
64: }

1: export function isWindowAvailable(): boolean {
2:   return typeof window !== "undefined";
3: }
4: 
5: export function isLocalStorageAvailable(): boolean {
6:   return isWindowAvailable() && typeof window.localStorage !== "undefined";
7: }
8: 
9: export function getLocalStorageItem(key: string): string | null {
10:   if (!isLocalStorageAvailable()) {
11:     return null;
12:   }
13: 
14:   try {
15:     return window.localStorage.getItem(key);
16:   } catch (error) {
17:     console.error(`Erro ao ler ${key} do localStorage:`, error);
18:     return null;
19:   }
20: }
21: 
22: export function setLocalStorageItem(key: string, value: string): boolean {
23:   if (!isLocalStorageAvailable()) {
24:     return false;
25:   }
26: 
27:   try {
28:     window.localStorage.setItem(key, value);
29:     return true;
30:   } catch (error) {
31:     console.error(`Erro ao salvar ${key} no localStorage:`, error);
32:     return false;
33:   }
34: }
35: 
36: export function removeLocalStorageItem(key: string): boolean {
37:   if (!isLocalStorageAvailable()) {
38:     return false;
39:   }
40: 
41:   try {
42:     window.localStorage.removeItem(key);
43:     return true;
44:   } catch (error) {
45:     console.error(`Erro ao remover ${key} do localStorage:`, error);
46:     return false;
47:   }
48: }
49: 
50: export function clearLocalStorage(): boolean {
51:   if (!isLocalStorageAvailable()) {
52:     return false;
53:   }
54: 
55:   try {
56:     window.localStorage.clear();
57:     return true;
58:   } catch (error) {
59:     console.error("Erro ao limpar localStorage:", error);
60:     return false;
61:   }
62: }
63: 
64: export function getCurrentPath(): string {
65:   if (!isWindowAvailable()) {
66:     return "";
67:   }
68:   return window.location.pathname;
69: }

