58: export async function createTransaction(data: CreateTransactionRequest): Promise<Transaction> {
59:   try {
60:     const response = await fetchApi("/account/transaction", {
61:       method: "POST",
62:       body: JSON.stringify(data),
63:     });
64: 
65:     const result: TransactionResponse = await response.json();
66:     return result.result;
67:   } catch (error) {
68:     throw new Error(error instanceof Error ? error.message : "Erro ao criar transação");
69:   }
70: }
