1: export function formatAccountNumber(accountId: string): string {
2:   if (!accountId) return "";
3: 
4:   const numericOnly = accountId.replace(/\D/g, "");
5: 
6:   if (numericOnly.length >= 7) {
7:     const last7 = numericOnly.slice(-7);
8:     return `${last7.slice(0, 6)}-${last7.slice(6)}`;
9:   }
10: 
11:   if (numericOnly.length >= 6) {
12:     return `${numericOnly.slice(-6)}-${numericOnly.slice(-1)}`;
13:   }
14: 
15:   return accountId.slice(-7) || accountId;
16: }
17: 
18: export function formatAccountLastDigits(accountId: string): string {
19:   if (!accountId) return "";
20:   const numericOnly = accountId.replace(/\D/g, "");
21:   return numericOnly.slice(-4);
22: }
